            if (!categoryHandled) {
                categoryHandled = true;
                if (manager._taskCategoryHandler(manager, ms)) {
                    continue;
                }
            }
            task._update(manager, ms, task);
        } else {
            task._update(manager, ms, task);
        }
    }
}
```

